def maxSubsetXOR(nums: list[int]) -> int:
    basis = [0] * 32
    for x in nums:
        for b in range(31, -1, -1):
            if (x >> b) & 1:
                if not basis[b]:
                    basis[b] = x
                    break
                x ^= basis[b]
    max_xor = 0
    for b in range(31, -1, -1):
        if (max_xor ^ basis[b]) > max_xor:
            max_xor ^= basis[b]
    return max_xor

